/** Recorded voice lines (generated by scripts/voices/generate.mjs). */
import VOICE_LINES from './voiceLines.gen';

/** File URL of a voiced line, or null when the line has no recording. The hash busts stale caches. */
export function voiceUrl(key: string, lines: Readonly<Record<string, string>> = VOICE_LINES): string | null {
  const hash = lines[key];
  return hash ? `/assets/audio/voice/${encodeURIComponent(key)}.m4a?v=${hash}` : null;
}

/** Music level while someone is speaking. */
export const VOICE_DUCK = 0.45;
/** Pause between consecutive lines of one speech, seconds. */
export const VOICE_GAP = 0.35;
